#include <stdio.h>
int main(void)
{
  int t, h, m, s;
  scanf("%d", &t);
  h = t / 3600;
  m = t % 3600 / 60;
  s = t % 60;
  printf("%02d:%02d:%02d\n", h, m, s);
  return 0;
}

