#include <stdio.h>
int main(void)
{
  int c, n = 0;
  while (c = getchar() != '\n')
    if (c >= 'a' && c <= 'z')
      n++;
  printf("%d\n", n);
  return 0;
}

#include <stdio.h>
int main(void)
{
  double price, total;
  int num;
  char vip;
  scanf("%f", &price);
  scanf("%d", num);
  scanf("%c", &vip);
  total = price * num;
  if (vip == 'Y')
    total = total * 0.9;
  printf("%.2f\n", total);
  return 0;
}

